3	/**
4	 * Thrown by {@link NormalizeOwnerTelephone} when an owner create request carries a telephone
5	 * that cannot be canonicalised to E.164 form (a {@code '+'} followed by 8 to 15 digits). Checked
6	 * so it appears in the {@code throws} clause and is routed to its escalation handler, which
7	 * responds 400.
8	 */
9	public class InvalidTelephoneException extends Exception {
10	
11	    public InvalidTelephoneException(String telephone) {
12	        super("Telephone must be a valid E.164 number (8 to 15 digits): " + telephone);
13	    }
14	}
